// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, uint8 useReverter) public {
        useReverter = useReverter & 1;

        uint256 seedBalance = bound(amount, 1, type(uint256).max / 2);
        vm.deal(address(this), seedBalance);
        (bool sent, ) = address(c).call{value: seedBalance}("");
        require(sent);

        address payable callee;
        if (useReverter == 1) {
            Reverter r = new Reverter();
            callee = payable(address(r));
        } else {
            Receiver r = new Receiver();
            callee = payable(address(r));
        }

        Controller ctrl = new Controller();
        if (useReverter == 1) {
            ctrl.setShouldRevert(true);
        }

        _shouldRevertOnReceive = (useReverter == 1);

        uint256 cBal = address(c).balance;
        vm.assume(cBal > 0);
        uint256 w = bound(amount, 1, cBal);

        bool ok;
        try c.withdraw(w) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || address(c).balance == cBal - w);
    }

    bool _shouldRevertOnReceive;

    receive() external payable {
        if (_shouldRevertOnReceive) revert("recv revert");
    }
}

contract Reverter { fallback() external payable { revert(); } }
contract Receiver { receive() external payable {} }
contract Controller {
    bool public shouldRevert;
    function setShouldRevert(bool v) external { shouldRevert = v; }
}
